import{_ as d,c as r,aU as o,a}from"./chunks/framework.DIXiA2XH.js";const u=JSON.parse('{"title":"08-公务员","description":"","frontmatter":{},"headers":[],"relativePath":"note/knowledge/08-公务员.md","filePath":"note/knowledge/08-公务员.md","lastUpdated":1785334184000}'),e={name:"note/knowledge/08-公务员.md"};function n(s,t,l,i,h,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="_08-公务员" tabindex="-1">08-公务员 <a class="header-anchor" href="#_08-公务员" aria-label="Permalink to &quot;08-公务员&quot;">​</a></h1><h2 id="等级" tabindex="-1">等级 <a class="header-anchor" href="#等级" aria-label="Permalink to &quot;等级&quot;">​</a></h2><h1 id="中国公务员职级体系表-从低到高" tabindex="-1">中国公务员职级体系表（从低到高） <a class="header-anchor" href="#中国公务员职级体系表-从低到高" aria-label="Permalink to &quot;中国公务员职级体系表（从低到高）&quot;">​</a></h1><table tabindex="0"><thead><tr><th>职级</th><th>对应职位示例</th><th>职级范围</th><th>权利范围</th></tr></thead><tbody><tr><td><strong>乡科级正职</strong></td><td>乡（镇）长、街道办事处主任、县教育局局长</td><td>二级主任科员至四级主任科员（16-22级）</td><td>负责基层行政管理（发展规划、公共服务等）</td></tr><tr><td><strong>乡科级副职</strong></td><td>副乡（镇）长、街道办副主任、县财政局副局长</td><td>四级主任科员至三级主任科员（17-24级）</td><td>协助正职管理基层事务，需5年以上基层经验</td></tr><tr><td><strong>县处级正职</strong></td><td>县长、地级市教育局局长、省级机关处长</td><td>二级调研员至四级调研员（12-18级）</td><td>统筹县域/市级部门工作（经济规划、政策执行）</td></tr><tr><td><strong>县处级副职</strong></td><td>副县长、地级市卫健委副主任、省级机关副处长</td><td>四级调研员至三级调研员（14-20级）</td><td>分管特定领域工作，晋升需正科满15年或选拔</td></tr><tr><td><strong>厅局级正职</strong></td><td>省教育厅厅长、地级市市长、直辖市下属局局长</td><td>一级巡视员至二级巡视员（8-13级）</td><td>主导省级部门/地级市重大决策（如清远市发展规划）</td></tr><tr><td><strong>厅局级副职</strong></td><td>省教育厅副厅长、地级市副市长、直辖市局副局长</td><td>二级巡视员至三级调研员（10-15级）</td><td>分管省级专项工作（近年&quot;80后&quot;干部密集出任，如珠海市长吴泽桐）</td></tr><tr><td><strong>省部级正职</strong></td><td>省长（如广东省长）、教育部长、直辖市市长</td><td>4-8级</td><td>全面领导省级/部委工作，参与国家政策制定</td></tr><tr><td><strong>省部级副职</strong></td><td>副省长、教育部副部长、直辖市副市长</td><td>6-10级</td><td>分管省级重点领域（如湖北省副省长主管经济），需中央考察晋升</td></tr><tr><td><strong>国家级副职</strong></td><td>国务院副总理、国务委员、全国政协副主席</td><td>2-4级</td><td>参与国家重大决策，分管核心领域（外交/经济/国防）</td></tr><tr><td><strong>国家级正职</strong></td><td>中共中央总书记、国务院总理、全国人大委员长</td><td>1级</td><td>领导国家政治/经济/军事核心事务，决策国家战略方向</td></tr></tbody></table><h3 id="表格说明" tabindex="-1">表格说明 <a class="header-anchor" href="#表格说明" aria-label="Permalink to &quot;表格说明&quot;">​</a></h3><ol><li><strong>职级范围</strong>：括号内为公务员级别（如16-22级），职级序列依据2019年《公务员职务与职级并行规定》；</li><li><strong>年轻化案例</strong>：厅局级干部出现&quot;80后&quot;（如清远市长陈金銮1981年出生）；</li><li><strong>特殊机制</strong>：正科级满15年未提拔可享副处级待遇（职级与职务并行制度）。</li></ol>',6)])])}const _=d(e,[["render",n]]);export{u as __pageData,_ as default};
